contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an Order struct's important fields as parameters. For simplicity
    // we pass most fields directly; arrays are passed as dynamic calldata
    // via memory parameters here (allowed). The test sends no ETH (msg.value=0).
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens
    ) public payable {
        require(address(this).balance >= 0, true);

        // Build minimal empty asset arrays
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        // Compose order
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // We will call fillOrder with an empty signature and empty floor token ids.
        bytes memory signature = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        // Try-catch to observe whether fillOrder reverts
        bool reverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256 posId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe expirations for the two related positions: orderHash and oppositeOrderHash
        bytes32 h = c.hashOrder(order);
        bytes32 opp = c.hashOppositeOrder(order);
        uint256 expA = c.positionExpirations(uint256(h));
        uint256 expB = c.positionExpirations(uint256(opp));

        // General rule:
        // If the call succeeded (not reverted) then exactly one of expA or expB equals block.timestamp + duration
        // and the other equals 0. If the call reverted, nothing is required (we can't observe changes), so allow either case.
        // We can't use block.timestamp inside assert (not allowed by checker), so we observe that when fillOrder succeeds
        // the contract must have set an expiration > 0 for exactly one of the two positions and the other must be zero.

        assert(
            reverted || (
                ((expA != 0) && (expB == 0)) || ((expB != 0) && (expA == 0))
            )
        );
    }

    receive() external payable {}
}

