            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory signature = new bytes(0);

        // ensure this contract has enough balance if premium is sent as ETH: but long call disallows native ETH per contract
        // So we won't send ETH. Call fillOrder and record revert.
        bool reverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256 positionId) {
