contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: order, signature, floorAssetTokenIds, and an ether value to forward when calling fillOrder
    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 value
    ) public payable {
        require(address(this).balance >= value, "not enough balance to forward");

        // Observe some preconditions/observables before calling
        bytes32 orderHash = c.hashOrder(order);
        bool wasCancelled = c.cancelledOrders(orderHash);

        // Save owner queries before call (may revert if not minted; catch via try)
        bool makerHadTokenBefore;
        bool fillerHadTokenBefore;
        address makerOwner;
        address fillerOwner;

        // check if maker token exists by trying ownerOf; if reverts then token not minted
        try c.ownerOf(uint256(orderHash)) returns (address owner) {
            makerHadTokenBefore = true;
            makerOwner = owner;
        } catch {
            makerHadTokenBefore = false;
            makerOwner = address(0);
        }

        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 posId = uint256(opposite);
        try c.ownerOf(posId) returns (address owner2) {
            fillerHadTokenBefore = true;
            fillerOwner = owner2;
        } catch {
            fillerHadTokenBefore = false;
            fillerOwner = address(0);
        }

        // Attempt the call and record if it reverted
        bool reverted;
        try c.fillOrder{value: value}(order, signature, floorAssetTokenIds) returns (uint256 newPosId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, check owners (if minted)
        bool makerHasAfter;
        bool fillerHasAfter;
        address makerOwnerAfter;
        address fillerOwnerAfter;

        try c.ownerOf(uint256(orderHash)) returns (address ownerA) {
            makerHasAfter = true;
            makerOwnerAfter = ownerA;
        } catch {
            makerHasAfter = false;
            makerOwnerAfter = address(0);
        }

        try c.ownerOf(posId) returns (address ownerB) {
            fillerHasAfter = true;
            fillerOwnerAfter = ownerB;
        } catch {
            fillerHasAfter = false;
            fillerOwnerAfter = address(0);
        }

        /* General rule asserted:
           If the call did NOT revert then BOTH of these must hold:
             - maker's order NFT (id = orderHash) exists and is owned by the order.maker
             - the opposite order NFT (id = hashOppositeOrder) exists and is owned by this contract's msg.sender (the filler), which in this test is address(this)
           Conversely, if the call reverted then neither of those post-conditions holds as a consequence of the call (i.e., at least one of them is false).

           We express it as: reverted XOR (makerHasAfter && makerOwnerAfter == order.maker && fillerHasAfter && fillerOwnerAfter == address(this))
        */
        assert(reverted != (makerHasAfter && makerOwnerAfter == order.maker && fillerHasAfter && fillerOwnerAfter == address(this)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Simpler test: take an order, signature, floor ids and value to forward.
    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 value
    ) public payable {
        // must have funds to forward if we intend to
        require(address(this).balance >= value, "insufficient balance to forward");
        // require baseAsset to be a contract address when sending ETH or when contract check expects it
        // we keep a simple precondition: duration not absurd and expiration in future
        require(order.duration < 10_000 days, "duration too long");
        require(block.timestamp < order.expiration, "order expired");

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        // Ensure neither token is minted initially to simplify reasoning (ownerOf would revert if minted).
        // If either is already minted this test is not applicable; require that ownerOf reverts for both.
        bool makerMintedBefore;
        try c.ownerOf(uint256(orderHash)) returns (address) {
            makerMintedBefore = true;
        } catch {
            makerMintedBefore = false;
        }
        require(!makerMintedBefore, "maker token already minted");

        bool fillerMintedBefore;
        try c.ownerOf(uint256(oppositeHash)) returns (address) {
            fillerMintedBefore = true;
        } catch {
            fillerMintedBefore = false;
        }
        require(!fillerMintedBefore, "filler token already minted");

        // Attempt the call and record whether it reverted
        bool reverted;
        try c.fillOrder{value: value}(order, signature, floorAssetTokenIds) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call: query owners (may revert if not minted)
        bool makerMintedAfter;
        address makerOwnerAfter;
        try c.ownerOf(uint256(orderHash)) returns (address ownerA) {
            makerMintedAfter = true;
            makerOwnerAfter = ownerA;
        } catch {
            makerMintedAfter = false;
            makerOwnerAfter = address(0);
        }

        bool fillerMintedAfter;
        address fillerOwnerAfter;
        try c.ownerOf(uint256(oppositeHash)) returns (address ownerB) {
            fillerMintedAfter = true;
            fillerOwnerAfter = ownerB;
        } catch {
            fillerMintedAfter = false;
            fillerOwnerAfter = address(0);
        }

        // General rule: if fillOrder did not revert, then maker token was minted to order.maker
        // and opposite token was minted to this contract (the filler, since this contract calls c).
        // Otherwise (if reverted) at least one of those postconditions is false.
        assert(reverted != (makerMintedAfter && makerOwnerAfter == order.maker && fillerMintedAfter && fillerOwnerAfter == address(this)));
    }

    receive() external payable {}
}

contract InvMutTest {
