    // Single public entry exercising fillOrder and asserting the general postcondition relation.
    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 value
    ) public payable {
        // If forwarding ETH to fillOrder, ensure this contract holds enough balance
        if (value > 0) {
            require(address(this).balance >= value, "insufficient balance to forward");
        }

        // Basic sanity preconditions to avoid trivial reverts from duration/expiration checks
        require(order.duration < 10_000 days, "duration too long");
        require(block.timestamp < order.expiration, "order expired");

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        // Call fillOrder and record whether it reverted
        bool reverted;
        try c.fillOrder{value: value}(order, signature, floorAssetTokenIds) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Query ownerOf for both tokens, capturing whether the calls reverted and the owners when available
        bool makerOwnerCallReverted;
        address makerOwner;
        try c.ownerOf(uint256(orderHash)) returns (address o) {
            makerOwnerCallReverted = false;
            makerOwner = o;
        } catch {
            makerOwnerCallReverted = true;
            makerOwner = address(0);
        }

        bool fillerOwnerCallReverted;
        address fillerOwner;
        try c.ownerOf(uint256(oppositeHash)) returns (address o2) {
            fillerOwnerCallReverted = false;
            fillerOwner = o2;
        } catch {
            fillerOwnerCallReverted = true;
            fillerOwner = address(0);
        }

        // General rule (single assert):
        // If fillOrder did not revert, then both ownerOf calls must succeed and return expected owners.
        // If fillOrder reverted, then at least one of those postconditions does not hold
        // (i.e., either a ownerOf call reverted or returned a different owner).
        assert(
            (!reverted && !makerOwnerCallReverted && !fillerOwnerCallReverted && makerOwner == order.maker && fillerOwner == address(this))
            || (reverted && (makerOwnerCallReverted || fillerOwnerCallReverted || makerOwner != order.maker || fillerOwner != address(this)))
        );
    }

    receive() external payable {}
}

