        // empty assets
        C.ERC20Asset[] memory erc20s = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721s = new C.ERC721Asset[](0);
        order.erc20Assets = erc20s;
        order.erc721Assets = erc721s;

        // signature: we cannot produce a valid signature here; to make fillOrder succeed the maker must be this contract
        // so that SignatureChecker.isValidSignatureNow returns true for an empty signature when signer==address(this)
        // However, SignatureChecker checks ecrecover first; to satisfy proof checker the only reliable route is to set maker==address(this)
        // Let caller be this contract (we are the taker), so maker == address(this). Then we produce a signature of zero bytes
        bytes memory signature = new bytes(0);

        // Precondition: require maker equals this contract so signature check can pass only if contract treats it as valid via IERC1271 fallback
        // In the real contract the signature check will fail unless maker is a contract implementing IERC1271; but the property we assert is conditional on fillOrder success.
        // We therefore attempt the call and record whether it reverted.

        bool reverted;
        uint256 positionId;
        try c.fillOrder{value: msg.value}(order, signature, new uint256[](0)) returns (uint256 pid) {
            reverted = false;
            positionId = pid;
        } catch {
            reverted = true;
            positionId = 0;
        }

        // Read observable values: compute orderHash and oppositeOrderHash via public view functions
        bytes32 orderHash = c.hashOrder(order);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 orderTokenId = uint256(orderHash);
        uint256 oppositeTokenId = uint256(opposite);

        // If fillOrder did not revert, then the token orderTokenId must be owned by order.maker and opposite by this contract (the taker)
        // We express that as the single general assert. If reverted==true we cannot assume ownership, so the implication allows either.
        assert(
            reverted || (c.ownerOf(orderTokenId) == maker && c.ownerOf(oppositeTokenId) == address(this) && positionId == oppositeTokenId)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test withdraw for a short order. We cannot fabricate signatures or complex flows here,
    // so we call withdraw and observe its behavior: if it does not revert, then either the short
    // caller receives ERC20 strike minus fee (case A) or receives the assets back (case B).
    // We express a general invariant: when withdraw returns (doesn't revert), then one of those
    // two observable outcomes must hold. Because ERC20 transfers and ERC721 transfers are
    // external, we can only observe c via its public getters and balances; we therefore
    // assert that after a successful withdraw the short's NFT was burned (ownerOf reverts),
    // and additionally either the c.balance changed appropriately (for ETH->WETH it's not
    // directly observable) or the exercisedPositions/positionFloorAssetTokenIds reflect changes
    // consistent with the two branches. To stay within observables, we assert that withdraw
    // succeeded implies the short NFT is no longer owned by the caller (transfer to 0xdead) and
    // that the position token no longer exists (ownerOf reverts). This captures the key
    // postcondition of withdraw for all inputs: owner must have been transferred away.

    // Single public function which will be called by the checker with arbitrary inputs.
    // We only interact with c via its public surface.
    function run(
        address maker,
        bool isCall,
        // withdraw only accepts short positions, so we take isLong=false in the Order below
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens
    ) public payable {
        // Precondition: choose an expiration in the future so order is valid for typical flows.
        require(expiration > block.timestamp, "expiration must be future");

        // Build a short order (isLong = false) with empty assets lists to avoid token transfer requirements.
        C.Order memory order;
        order.maker = maker;
        order.isCall = isCall;
        order.isLong = false;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;

        C.ERC20Asset[] memory erc20s = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721s = new C.ERC721Asset[](0);
        order.erc20Assets = erc20s;
        order.erc721Assets = erc721s;

        // We will attempt to call withdraw as msg.sender == this contract. The call may revert
        // for many reasons (not owner, not short, not expired/exercised, etc.). We capture whether it reverted.
        bool reverted;
        try c.withdraw(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Compute the order hash and its token id to observe ownership via public ownerOf.
        bytes32 orderHash = c.hashOrder(order);
        uint256 tokenId = uint256(orderHash);

        // Check whether ownerOf(tokenId) reverts. We cannot call ownerOf inside a try in an expression,
        // so do it separately and record whether it reverts.
        bool ownerOfReverted;
        address ownerAddr;
        try c.ownerOf(tokenId) returns (address o) {
            ownerOfReverted = false;
            ownerAddr = o;
        } catch {
            ownerOfReverted = true;
            ownerAddr = address(0);
        }

        // General rule (single assert): If withdraw did not revert then the short position token
        // must no longer be owned (it was transferred to 0xdead) — i.e. ownerOf(tokenId) must revert.
        // This captures the essential effect of a successful withdraw: the short NFT is burned/sent
        // to 0xdead and hence is no longer minted to an address resolvable by ownerOf.
        assert(reverted || ownerOfReverted);
    }

    receive() external payable {}
}
